/**
 * Advanced Course Configuration (Community Edition)
 *
 * This file is generated by the publish pipeline (scripts/publish_community.py):
 * Only carries free course metadata (phase-01, first 5 sessions), no paid content.
 */

export interface Lesson {
  id: string
  title: string
  file: string  // Markdown File path (relative to docs/07-courses/v3.0/)
  order: number
}

export interface CourseCategory {
  id: string
  name: string
  icon: string
  description: string
  lessonCount: number
  lessons: Lesson[]
}

/** Number of courses available for free */
export const FREE_LESSON_COUNT = 5

/**
 * Determine if a course is free
 */
export function isFreeLesson(order: number): boolean {
  return order <= FREE_LESSON_COUNT
}

/** Free course classification (first 5 lessons, reserved for community version) */
const communityCourseCategories: CourseCategory[] = [
  {
    id: 'phase-01-discover',
    name: 'discovery phase',
    icon: '🔍',
    description: 'Find the ones worth researching from 6,000 stocks',
    lessonCount: 5,
    lessons: [
      { id: 'lesson-01', title: 'Lesson 1: Stock Screening (Natural Language+conditional filtering)', file: 'phase-01-discover/lesson-01-stock-screening.md', order: 1 },
      { id: 'lesson-02', title: 'Lesson 2: Batch Analysis (Single≤10 only)', file: 'phase-01-discover/lesson-02-batch-analysis.md', order: 2 },
      { id: 'lesson-03', title: 'Lesson 3: Introduction to Single Stock Research (Level 5 Depth)', file: 'phase-01-discover/lesson-03-single-analysis-basic.md', order: 3 },
      { id: 'lesson-04', title: 'Lesson 4: Advanced Single Stock Research·multi-scenario debate', file: 'phase-01-discover/lesson-04-single-analysis-multi-scenario.md', order: 4 },
      { id: 'lesson-05', title: 'Lesson 5: Common Mistakes in the Discovery Phase', file: 'phase-01-discover/lesson-05-discover-pitfalls.md', order: 5 },
    ]
  }
]

/** Full course classification (community version: only free part) */
export const advancedCourseCategories: CourseCategory[] = [
  ...communityCourseCategories
]

/**
 * Get course information based on category ID and course ID
 */
export function getLesson(categoryId: string, lessonId: string): Lesson | null {
  const category = advancedCourseCategories.find(cat => cat.id === categoryId)
  if (!category) return null

  return category.lessons.find(lesson => lesson.id === lessonId) || null
}

/**
 * Get course information based on course file path
 */
export function getLessonByFile(file: string): { category: CourseCategory, lesson: Lesson } | null {
  for (const category of advancedCourseCategories) {
    const lesson = category.lessons.find(l => l.file === file)
    if (lesson) {
      return { category, lesson }
    }
  }
  return null
}

/**
 * Get previous and next lessons
 */
export function getAdjacentLessons(categoryId: string, lessonId: string): {
  prev: { category: CourseCategory, lesson: Lesson } | null
  next: { category: CourseCategory, lesson: Lesson } | null
} {
  const category = advancedCourseCategories.find(cat => cat.id === categoryId)
  if (!category) {
    return { prev: null, next: null }
  }

  const lessonIndex = category.lessons.findIndex(l => l.id === lessonId)
  if (lessonIndex === -1) {
    return { prev: null, next: null }
  }

  // Previous lesson
  let prev: { category: CourseCategory, lesson: Lesson } | null = null
  if (lessonIndex > 0) {
    prev = { category, lesson: category.lessons[lessonIndex - 1] }
  } else {
    const categoryIndex = advancedCourseCategories.findIndex(cat => cat.id === categoryId)
    if (categoryIndex > 0) {
      const prevCategory = advancedCourseCategories[categoryIndex - 1]
      if (prevCategory.lessons.length > 0) {
        prev = {
          category: prevCategory,
          lesson: prevCategory.lessons[prevCategory.lessons.length - 1]
        }
      }
    }
  }

  // next lesson
  let next: { category: CourseCategory, lesson: Lesson } | null = null
  if (lessonIndex < category.lessons.length - 1) {
    next = { category, lesson: category.lessons[lessonIndex + 1] }
  } else {
    const categoryIndex = advancedCourseCategories.findIndex(cat => cat.id === categoryId)
    if (categoryIndex < advancedCourseCategories.length - 1) {
      const nextCategory = advancedCourseCategories[categoryIndex + 1]
      if (nextCategory.lessons.length > 0) {
        next = { category: nextCategory, lesson: nextCategory.lessons[0] }
      }
    }
  }

  return { prev, next }
}
